return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2026-09-28 09:40:11+0000','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'Plugins - WPS Hide Login - Stable (latest release)','language'=>'sr_RS','messages'=>['Dashboard'=>'Контролна табла','WPBoutik'=>'WPBoutik','You want to find out how to simplify ecommerce with WordPress, try'=>'Ако желите да сазнате како да поједноставите е-трговину уз Вордпрес, испробајте','WPS Hide Login : Please note that the comment_registration option “Users must be registered and logged in to comment” is activated on your site, the connection link will not be hidden on the comments block.'=>'WPS Hide Login : имајте на уму да је на вашем сајту укључена могућност comment_registration „Корисници морају бити регистровани и пријављени да би коментарисали“, па веза за пријављивање неће бити сакривена у блоку коментара.','WPS Hide Login : Please note, if you check the comment_registration option "Users must be registered and logged in to comment", the login link will not be hidden on the comment block.'=>'WPS Hide Login : имајте на уму да, ако штиклирате могућност comment_registration „Корисници морају бити регистровани и пријављени да би коментарисали“, веза за пријављивање неће бити сакривена у блоку коментара.','WPServeur, NicolasKulka, wpformation'=>'WPServeur, NicolasKulka, wpformation','WPS Bidouille'=>'WPS Bidouille','and'=>'и','Redirect URL when someone tries to access the wp-login.php page and the wp-admin directory while not logged in.'=>'URL преусмеравања када неко покуша да приступи страници wp-login.php и директоријуму wp-admin без пријаве.','Protect your website by changing the login URL and preventing access to the wp-login.php page and the wp-admin directory to non-connected people.'=>'Заштитите свој веб сајт променом URL-а за пријављивање и спречавањем приступа страници wp-login.php и директоријуму wp-admin особама које нису пријављене.','WPS Limit Login'=>'WPS Limit Login','WPS Cleaner'=>'WPS Cleaner','the plugin'=>'додатак','Discover our other plugins:'=>'Откријте наше друге додатке:','Redirection url default'=>'Подразумевани URL преусмеравања','Redirection url'=>'URL преусмеравања','WordPress specialized hosting'=>'Хостинг специјализован за Вордпрес','https://wpserveur.net'=>'https://wpserveur.net','This has been disabled'=>'Ово је онемогућено','Protect your website by changing the login URL and preventing access to wp-login.php page and wp-admin directory while not logged-in'=>'Заштитите свој веб сајт тако што ћете променити УРЛ адресу за пријављивање и спречити приступ wp-login.php страни и wp-admin директоријуму док нисте пријављени','Settings'=>'Podešavanja','This feature is not enabled.'=>'Ова функција није омогућена','Login url'=>'URL за prijavu','WPS Hide Login'=>'WPS Hide Login','Networkwide default'=>'Подразумевана мрежа','This option allows you to set a networkwide default, which can be overridden by individual sites. Simply go to to the site’s permalink settings to change the url.'=>'Ова могућност вам омогућава да поставите подразумевану мрежну вредност, која може бити промењена код појединачних сајтова. Једноставно идите на страницу поставке сталних веза како бисте променили урл.','WPS Hide Login could not be activated because you already have Rename wp-login.php active. Please uninstall rename wp-login.php to use WPS Hide Login'=>'WPS Hide Login се не може укључити јер већ имате укључен Rename wp-login.php. Да деинсталирате rename wp-login.php да бисте користили WPS Hide Login','Please upgrade to the latest version of WordPress to activate'=>'Надоградите Вордпрес на најновију верзију како би сте успешно активирали','Your login page is now here: <strong><a href="%1$s">%2$s</a></strong>. Bookmark this page!'=>'Ваша страница за пријављивање је сада овде: <strong><a href="%1$s">%2$s</a></strong>. Сачувајте ову страницу у обележивачима!',